"""r232 (r176 roll-out): rewrite octet-change's step text in lib/md.js markup, fr and en.
Tones as the card and the HMAC room draw them: {1|} violet a key, {2|} blue the IV,
{3|} gold the ciphertext, {4|} green the seal, {r|} red what Eve rewrites. Run once; idempotent."""
import json, re, sys
from pathlib import Path

F = Path(__file__).resolve().parent.parent / 'octet-change/js/i18n.js'
